    private clearRectangle() {
        if (!this.rectangleStart && !this.rectangle) return false

        this.rectangleStart = null
        this.rectangle = null
        this.dispatchEvent(new Event(SELECTION_RECTANGLE_CHANGED_EVENT))

        return true
    }

    private setRectangle(rectangle: DiagramRectangle) {
        const current = this.rectangle
        if (current && current.height === rectangle.height && current.width === rectangle.width
            && current.x === rectangle.x && current.y === rectangle.y) return false

        this.rectangle = rectangle
        this.dispatchEvent(new Event(SELECTION_RECTANGLE_CHANGED_EVENT))

        return true
    }

    private publish(changedIdentities: readonly DiagramSelectionIdentity[]) {
        this.bindBoundaryGeometry()
        this.updateBoundary()
        for (const identity of changedIdentities) this.dispatchEvent(new Event(selectedChangedEvent(identity)))
        this.dispatchEvent(new Event(SELECTION_MEMBERSHIP_CHANGED_EVENT))
    }

    private bindBoundaryGeometry() {
        this.boundaryUnsubscribes.forEach((unsubscribe) => unsubscribe())
        this.boundaryUnsubscribes = []
        if (this.selection.length < 2) return
        for (const { objectId, objectKind } of this.selection) {
            if (objectKind === 'edge') {
                this.boundaryUnsubscribes.push(this.geometry.subscribeEdgeGeometryField(objectId, 'points', this.updateBoundary))
                this.boundaryUnsubscribes.push(this.geometry.subscribeEdgeGeometryField(objectId, 'controlPoint', this.updateBoundary))
                continue
            }
            for (const field of ['x', 'y', 'width', 'height'] as const) {
                const subscribe = objectKind === 'node'
                    ? this.geometry.subscribeNodeGeometryField
                    : this.geometry.subscribeGroupGeometryField
                this.boundaryUnsubscribes.push(subscribe(objectId, field, this.updateBoundary))
            }
        }
    }

    private updateBoundary = () => {
        let left = Infinity
        let top = Infinity
        let right = -Infinity
        let bottom = -Infinity
        if (this.selection.length > 1) {
            for (const { objectId, objectKind } of this.selection) {
                if (objectKind === 'edge') {
                    const route = this.geometry.getEdgeRouteSnapshot(objectId)
                    const controlPoint = this.geometry.getEdgeControlPointSnapshot(objectId)
                    for (const point of controlPoint ? [...route, controlPoint] : route) {
                        left = Math.min(left, point.x)
                        top = Math.min(top, point.y)
                        right = Math.max(right, point.x)
                        bottom = Math.max(bottom, point.y)
                    }
                    continue
                }
                const box = this.readBox(objectKind, objectId)
                if (!box) continue
                left = Math.min(left, box.x)
                top = Math.min(top, box.y)
                right = Math.max(right, box.x + box.width)
                bottom = Math.max(bottom, box.y + box.height)
            }
        }
        const next = Number.isFinite(left) ? { x: left, y: top, width: right - left, height: bottom - top } : null
        const current = this.boundary
        if (current?.x === next?.x && current?.y === next?.y
            && current?.width === next?.width && current?.height === next?.height) return
        this.boundary = next
        this.dispatchEvent(new Event(SELECTION_BOUNDARY_CHANGED_EVENT))
    }

    private subscribe(eventType: string, listener: () => void) {
        this.addEventListener(eventType, listener)

        return () => this.removeEventListener(eventType, listener)
    }
}

export const diagramSelectionService = register('diagramSelectionService', new DiagramSelectionService())

import type { DiagramWaypoint } from './diagram_data';

export interface DiagramPoint {
    x: number;
    y: number;
}

export interface DiagramRectangle extends DiagramPoint {
    height: number;
    width: number;
}

function pointInsideRectangle(point: DiagramPoint, rectangle: DiagramRectangle) {
    return point.x >= rectangle.x && point.x <= rectangle.x + rectangle.width
        && point.y >= rectangle.y && point.y <= rectangle.y + rectangle.height;
}

function orientation(first: DiagramPoint, second: DiagramPoint, third: DiagramPoint) {
    return (second.y - first.y) * (third.x - second.x) - (second.x - first.x) * (third.y - second.y);
}

function pointOnSegment(first: DiagramPoint, second: DiagramPoint, point: DiagramPoint) {
    return point.x >= Math.min(first.x, second.x) && point.x <= Math.max(first.x, second.x)
        && point.y >= Math.min(first.y, second.y) && point.y <= Math.max(first.y, second.y);
}

function segmentsIntersect(
    firstStart: DiagramPoint,
    firstEnd: DiagramPoint,
    secondStart: DiagramPoint,
    secondEnd: DiagramPoint,
) {
    const firstStartOrientation = orientation(firstStart, firstEnd, secondStart);
    const firstEndOrientation = orientation(firstStart, firstEnd, secondEnd);
    const secondStartOrientation = orientation(secondStart, secondEnd, firstStart);
    const secondEndOrientation = orientation(secondStart, secondEnd, firstEnd);
    const firstSegmentStraddles = (firstStartOrientation > 0 && firstEndOrientation < 0)
        || (firstStartOrientation < 0 && firstEndOrientation > 0);
    const secondSegmentStraddles = (secondStartOrientation > 0 && secondEndOrientation < 0)
        || (secondStartOrientation < 0 && secondEndOrientation > 0);
    if (firstSegmentStraddles && secondSegmentStraddles) return true;
    if (firstStartOrientation === 0 && pointOnSegment(firstStart, firstEnd, secondStart)) return true;
    if (firstEndOrientation === 0 && pointOnSegment(firstStart, firstEnd, secondEnd)) return true;
    if (secondStartOrientation === 0 && pointOnSegment(secondStart, secondEnd, firstStart)) return true;

    return secondEndOrientation === 0 && pointOnSegment(secondStart, secondEnd, firstEnd);
}

/** Builds an axis-aligned rectangle regardless of drag direction. */
export function diagramRectangleBetween(start: DiagramPoint, end: DiagramPoint): DiagramRectangle {
    return Object.freeze({
        height: Math.abs(end.y - start.y),
        width: Math.abs(end.x - start.x),
        x: Math.min(start.x, end.x),
        y: Math.min(start.y, end.y),
    });
}

/** Reports inclusive overlap, so touching a selection boundary counts as intersection. */
export function diagramRectangleIntersectsBox(rectangle: DiagramRectangle, box: DiagramRectangle) {
    return rectangle.x <= box.x + box.width && rectangle.x + rectangle.width >= box.x
        && rectangle.y <= box.y + box.height && rectangle.y + rectangle.height >= box.y;
}

/** Reports whether any point or segment of an edge route intersects the rectangle. */
export function diagramRectangleIntersectsRoute(
    rectangle: DiagramRectangle,
    points: readonly DiagramWaypoint[],
) {
    if (points.some((point) => pointInsideRectangle(point, rectangle))) return true;

    const topLeft = { x: rectangle.x, y: rectangle.y };
    const topRight = { x: rectangle.x + rectangle.width, y: rectangle.y };
    const bottomRight = { x: rectangle.x + rectangle.width, y: rectangle.y + rectangle.height };
    const bottomLeft = { x: rectangle.x, y: rectangle.y + rectangle.height };
    const rectangleSegments = [
        [topLeft, topRight],
        [topRight, bottomRight],
        [bottomRight, bottomLeft],
        [bottomLeft, topLeft],
    ] as const;

    return points.slice(1).some((point, index) => (
        rectangleSegments.some(([start, end]) => segmentsIntersect(points[index], point, start, end))
    ));
}

function quadraticCoordinate(start: number, control: number, end: number, progress: number) {
    const remaining = 1 - progress;
    return remaining * remaining * start + 2 * remaining * progress * control + progress * progress * end;
}

function quadraticBoundaryCrossings(start: number, control: number, end: number, boundary: number) {
    const quadratic = start - 2 * control + end;
    const linear = 2 * (control - start);
    const constant = start - boundary;
    if (quadratic === 0) return linear === 0 ? [] : [-constant / linear];

    const discriminant = linear * linear - 4 * quadratic * constant;
    if (discriminant < 0) return [];
    const root = Math.sqrt(discriminant);
    return [(-linear - root) / (2 * quadratic), (-linear + root) / (2 * quadratic)];
}

/** Tests the visible quadratic curve, including a tangency with the rectangle boundary. */
export function diagramRectangleIntersectsQuadraticCurve(
    rectangle: DiagramRectangle,
    start: DiagramPoint,
    control: DiagramPoint,
    end: DiagramPoint,
) {
    if (pointInsideRectangle(start, rectangle) || pointInsideRectangle(end, rectangle)) return true;

    const left = rectangle.x;
    const right = left + rectangle.width;
    const top = rectangle.y;
    const bottom = top + rectangle.height;
    const crossesVertical = [left, right].some((boundary) => (
        quadraticBoundaryCrossings(start.x, control.x, end.x, boundary).some((progress) => {
            if (progress < 0 || progress > 1) return false;
            const y = quadraticCoordinate(start.y, control.y, end.y, progress);
            return y >= top && y <= bottom;
        })
    ));
    if (crossesVertical) return true;

    return [top, bottom].some((boundary) => (
        quadraticBoundaryCrossings(start.y, control.y, end.y, boundary).some((progress) => {
            if (progress < 0 || progress > 1) return false;
            const x = quadraticCoordinate(start.x, control.x, end.x, progress);
            return x >= left && x <= right;
        })
    ));
}

